  ui_story_5008_50080601_15_dialog_content = "Hmm... Déjame sentir tu cabeza.",
  ui_story_5008_50080601_16_dialog_content = "Tu temperatura parece normal.",
  ui_story_5008_50080601_17_dialog_content = "Yo... Creo que tengo conjuntivitis... ¡Mi ojo izquierdo ha comenzado a derramar lágrimas y está todo rojo e hinchado! Coo...",
  ui_story_5008_50080601_18_dialog_content = "Te vi frotándote los ojos con tanto vigor hace un momento, pero no vi lágrimas.",
  ui_story_5008_50080601_19_dialog_content = "Coo... Creo que este lugar podría estar infestado de pulgas... Me pica tanto...",
  ui_story_5008_50080601_20_dialog_content = "Necesito... Coo, coo... ¡Pide la baja por enfermedad!",
  ui_story_5008_50080601_21_dialog_content = "Te has arrancado tanto pelo... ¿No te duele?",
  ui_story_5008_50080601_22_dialog_content = "Dove, como miembros de Unión de Mensajería, debemos cumplir con el código de mensajería.",
  ui_story_5008_50080601_23_dialog_content = "Debemos terminar lo que prometimos lograr.",
  ui_story_5008_50080601_24_dialog_content = "Aunque soy muy consciente de cuánto amas exactamente tu sueño, debemos cumplir con nuestro deber.",
  ui_story_5008_50080601_25_dialog_content = "Así que... Debo rechazar su solicitud.",
  ui_story_5008_50080601_26_dialog_content = "Una vez que terminemos aquí, lo ayudaré a solicitar tiempo libre en la sucursal de Illumina. ¿Qué tal suena eso?",
  ui_story_5008_50080601_27_dialog_content = "Coo, coo, coo... Muy bien...",
  ui_story_5008_50080701_1_dialog_content = "¿Qué es este contenedor? Parece familiar.",
  ui_story_5008_50080701_2_dialog_content = "¿Qué podría haber dentro de él? No podemos llevarlo con nosotros, y no tiene sentido dejarlo aquí...",
  ui_story_5008_50080701_3_dialog_content = "*toc, toc* También se siente bastante frágil. ¡Ni siquiera creo que sea lo suficientemente estable como para dormir! ¡Coo, coo!",
  ui_story_5008_50080701_4_dialog_content = "¡Dove! ¡Es obvio que es un jadón!",
  ui_story_5008_50080701_5_dialog_content = "¿Cómo es que no sabes qué es un jarrón? ¿No juedas con plantas en Idumina?",
  ui_story_5008_50080701_6_dialog_content = "¿Jugar con plantas? ¿Estás hablando de... arreglos florales? ¿Plantando árboles?",
  ui_story_5008_50080701_7_dialog_content = "¡Ciedto! ¡Adeglo flodal!",
  ui_story_5008_50080701_8_dialog_content = "¿Arreglo floral? Creo que lo vi en un libro una vez.",
  ui_story_5008_50080701_9_dialog_content = "Solo he visto floreros pequeños... No grandes como este.",
  ui_story_5008_50080701_10_dialog_content = "¡Creo que la decoración de este jarrón es como la diadema de PlayerName!",
  ui_story_5008_50080701_11_dialog_content = "Esta combinación de colores y estilo son exclusivos de Eraveil.",
  ui_story_5008_50080701_12_dialog_content = "Coo... Este jarrón parece muy familiar. Sé que lo he visto en alguna parte antes.",
  ui_story_5008_50080701_13_dialog_content = "Hmm... ¿Eso es porcelana? ¿Fabrican podcelana en Illumina?",
  ui_story_5008_50080701_14_dialog_content = "¡Coo! ¡No, no hacemos porcelana...! ¡Urk!",
  ui_story_5008_50080701_15_dialog_content = "¡Ah! ¡Eso es! ¡Lo vi en la sucursal de Illumina! He visto floreros como este en la sucudsal de Illumina... ¡Me refiero a la sucursal de Illumina!",
  ui_story_5008_50080701_16_dialog_content = "Como la red de transporte aquí ya no está operativa, los jarrones como este solo se han visto en Illumina.",
  ui_story_5008_50080701_17_dialog_content = "Ese jarrón debe haber sido enviado de Eraveil a Illumina.",
  ui_story_5008_50080701_18_dialog_content = "Ese jarrón estuvo en la sucursal de Illumina durante tanto tiempo... Muestra que el receptor no tuvo tiempo de levantarlo.",
  ui_story_5008_50080701_19_dialog_content = "O quizás no había forma de que lo recogieran.",
  ui_story_5008_50080701_20_dialog_content = "Coo, coo...",
  ui_story_5008_50080701_21_dialog_content = "No me di cuenta... En realidad era un paquete Eraveil...",
  ui_story_5008_50080701_22_dialog_content = "Eso no es un problema. Cuando regreses, puedes darle el jarrón al Celestita y dejar que lo coloque sobre el Colossus.",
  ui_story_5008_50080701_23_dialog_content = "Y no son solo los jarrones abandonados, también hay más paquetes en Umbraton esperando a que él los firme.",
  ui_story_5008_50080701_24_dialog_content = "Los propietarios de esas parcelas probablemente no tenían ningún parentesco con él.",
  ui_story_5008_50080701_25_dialog_content = "Pero supongo que eso es todo lo que podemos hacer.",
  ui_story_5008_50080701_26_dialog_content = "Porque PlayerName es el único que queda.",
  ui_story_5008_50080701_27_dialog_content = "Coo...",
  ui_story_5008_50080701_28_dialog_content = "Creo que debe tener muchos paquetes y correo para firmar...",
  ui_story_5008_50080701_29_dialog_content = "Ese correo ha estado en el depósito de Umbraton durante diecisiete años. Es hora de que vuelva aquí.",
  ui_story_5008_50080701_30_dialog_content = "Naroxel, ¿Illumina estuvo en contacto con Eraveil hace tanto tiempo?",
  ui_story_5008_50080701_31_dialog_content = "Por supuesto. Después de todo, la red de transporte se estableció hace mucho tiempo.",
  ui_story_5008_50080701_32_dialog_content = "Tweety, ¿no escuchaste con atención durante tu entrenamiento?",
  ui_story_5008_50080701_33_dialog_content = "Todo esto se describe en el manual introductorio de Unión de Mensajería.",
  ui_story_5008_50080701_34_dialog_content = "Oh... Supongo que me olvidar...",
  ui_story_5008_50080701_35_dialog_content = "Eres muy tonto, Tweety.",
  ui_story_5008_50080701_36_dialog_content = "Dove, parece que el acento de Tweety se ha apoderado de ti.",
  ui_story_5008_50080701_37_dialog_content = "<anim type=Shake>—¡Pffffft!</anim>",
  ui_story_5008_50080701_38_dialog_content = "¡No digas eso! ¡Coo! ¡Coo!",
  ui_story_5008_50080801_1_dialog_content = "Uf... ¡Finalmente hemos tedminado de limpiad!",
  ui_story_5008_50080801_2_dialog_content = "Aunque no todo está en oden aquí, ¡al menos podemos echad un vistazo ahoda y ver qué es!",
  ui_story_5008_50080801_3_dialog_content = "Ahora que este lugar ha sido limpiado...",
  ui_story_5008_50080801_4_dialog_content = "Terminamos con la primera etapa... Naroxel, ¿puedo regresar e informar?",
  ui_story_5008_50080801_5_dialog_content = "¡Podemos reparar todo aquí la próxima vez! ¡Coo, coo!",
  ui_story_5008_50080801_6_dialog_content = "Dove, en mi solicitud de asistencia, solicité:",
  ui_story_5008_50080801_7_dialog_content = "\"...asistencia a ser trasladada a Correos de Eraveil hasta que se reanude el funcionamiento de correos\".",
  ui_story_5008_50080801_8_dialog_content = "¡Dove! ¡Dove se plantó boca abajo en el suelo!",
  ui_story_5008_50080801_9_dialog_content = "¡Dove! ¡Despierta, despierta y brilla!",
  ui_story_5008_50080801_10_dialog_content = "¡Coo! ¡No estoy durmiendo! ¿No ves que me desmayé?",
  ui_story_5008_50080801_11_dialog_content = "¿No estás cansado después de toda esta limpieza, Tweety?",
  ui_story_5008_50080801_12_dialog_content = "Ahora que lo mencionas, esdoy un poco cansado.",
  ui_story_5008_50080801_13_dialog_content = "¡Pero eso es porque yo he estado trabajando! ¡Tu has estado holgazaneando!",
  ui_story_5008_50080801_14_dialog_content = "No puedo discutir con eso.",
  ui_story_5008_50080801_15_dialog_content = "¡Coo, coo! ¡He trabajado mucho más duro que nunca en Illumina! ¡Coo!",
  ui_story_5008_50080801_16_dialog_content = "Bueno, ustedes dos hicieron un muy buen trabajo hace un momento.",
  ui_story_5008_50080801_17_dialog_content = "Ahora casi podemos ver cómo solía ser esta oficina de correos... Pero aún no es suficiente.",
  ui_story_5008_50080801_18_dialog_content = "PlayerName está luchando contra el enemigo en Eraveil. Quizás las cosas van bien, quizás no...",
  ui_story_5008_50080801_19_dialog_content = "Todo lo que sabemos es que no podemos permitirnos perder el tiempo. La oficina de correos debe restaurarse lo antes posible.",
  ui_story_5008_50080801_20_dialog_content = "Aunque no ha sido fácil hasta ahora, la buena noticia es que hemos completado todo el tedioso trabajo de limpieza.",
  ui_story_5008_50080801_21_dialog_content = "Ahora podemos realizar los trabajos de reparación.",
  ui_story_5008_50080801_22_dialog_content = "¿No sientes curiosidad por saber cómo la oficina de correos de Eraveil sirvió a los celestitas?",
  ui_story_5008_50080801_23_dialog_content = "¿Estás buscando una respuesta real o...?",
  ui_story_5008_50080801_24_dialog_content = "No estoy...",
  ui_story_5008_50080801_25_dialog_content = "¡Quiero saber!",
  ui_story_5008_50080801_26_dialog_content = "Entonces continuemos todos haciendo nuestro mejor esfuerzo.",
  ui_story_5008_50080801_27_dialog_content = "Mira por la ventana. Sé testigo de la belleza natural de Eraveil.",
  ui_story_5008_50080801_28_dialog_content = "Creo que la naturaleza nos está otorgando felicidad sin darnos cuenta.",
  ui_story_5008_50080801_29_dialog_content = "Hmm... ¡Creo que lo entiendo, Naroxel!",
  ui_story_5008_50080801_30_dialog_content = "¡Es porque trabajamos muy duro! Por eso podemos ver tanta belleza, ¿no es así?",
  ui_story_5008_50080801_31_dialog_content = "Creo...",
  ui_story_5008_50080801_32_dialog_content = "Repartiré más bocadillos de la unión. La siguiente tarea puede ser algo más difícil.",
  ui_story_5008_50080801_33_dialog_content = "¡Wow! ¡Bien!",
  ui_story_5008_50080801_34_dialog_content = "Espero no tener el mismo que la última vez, coo...",
  ui_story_5008_50080801_35_dialog_content = "No, esta vez te daré tu sabor favorito.",
  ui_story_5008_50080801_36_dialog_content = "Dove — Sabor Illumina Quilt.",
  ui_story_5008_50080801_37_dialog_content = "Tweety — sabor a flor de cerezo.",
  ui_story_5008_50080801_38_dialog_content = "Mmm... ¡Delicioso! ¡Gracias, Naroxel!",
  ui_story_5008_50080801_39_dialog_content = "¿Conoces el favorito \"Illumina Quilt\" de Dove...?",
  ui_story_5008_50080801_40_dialog_content = "¿Eso significa que cada lugad tiene sus propios bocadillos especiales con sabor quilt?",
  ui_story_5008_50080801_41_dialog_content = "Hmm... Ya he probado el sabor \"Rediesel Quilt\".",
  ui_story_5008_50080801_42_dialog_content = "No lo recomendaría.",
  ui_story_5008_50080801_43_dialog_content = "Coo... Tengo muchas ganas de dormir después de esa merienda... Coo...",
  ui_story_5008_50080801_44_dialog_content = "Ahora que nos hemos quedado sin bocadillos sindicales, continuemos con nuestro proyecto.",
  ui_story_5008_50080801_45_dialog_content = "También es hora de aumentar la moral...",
  ui_story_5008_50080801_46_dialog_content = "¿Inyección de moral?",
  ui_story_5008_50080801_47_dialog_content = "¡Dove, Tweety! ¡Han hecho un trabajo increíble!",
  ui_story_5008_50080801_48_dialog_content = "¡Ambos son excelentes mensajeros y hasta ahora han personificado el credo de la Unión de Mensajería!",
  ui_story_5008_50080801_49_dialog_content = "¡Digámoslo en voz alta, juntos!",
  ui_story_5008_50080801_50_dialog_content = "¡La Unión de Mensajería siempre cumple!",
  ui_story_5008_50080801_51_dialog_content = "Muy bien hecho.",
  ui_story_5008_50080801_52_dialog_content = "¡Naroxel realmente fedicitó mi tabajo!",
  ui_story_5008_50080801_53_dialog_content = "¡Ah! ¡Coo! ¡Disculpa, Naroxel!",
  ui_story_5008_50080801_54_dialog_content = "Normalmente, no se puede distinguir el sabor de los bocadillos de unión del empaque exterior...",
  ui_story_5008_50080801_55_dialog_content = "Entonces, ¿cómo lograste elegir nuestros dos sabores favoritos sin abrirlos?",
  ui_story_5008_50080801_56_dialog_content = "Eso fue fácil.",
  ui_story_5008_50080801_57_dialog_content = "Dejé que Singh y Poite lamieran todos los bocadillos sindicales en mi bolso.",
  ui_story_5008_50080801_58_dialog_content = "Singh y Poite, los dos cuclillos que me siguen a todas partes.",
  ui_story_5008_50080801_59_dialog_content = "Hice un pequeño agujero en el paquete y dejé que lo lamieran, luego me dijeron el sabor.",
  ui_story_5008_50080801_60_dialog_content = "Después de que lamieron los bocadillos, elegí tus sabores favoritos y los volví a empaquetar.",
  ui_story_5008_50080801_61_dialog_content = "¿¡Coo!? ¿¡Qué!?",
  ui_story_5008_50080801_62_dialog_content = "¡Me preguntaba por qué sabía a saliva!",
  ui_story_5008_50080901_1_dialog_content = "¿Por qué no funciona esta lámpara de pared?",
  ui_story_5008_50080901_2_dialog_content = "¡Lo arreglé exactamente como arreglo las lámparas en Hotel Flod de Dube!",
  ui_story_5008_50080901_3_dialog_content = "Quizás las lámparas de Eraveil sean distintas a las del Hotel Flor de Nube...",
  ui_story_5008_50080901_4_dialog_content = "Hmm... Hace sentido... ¿Lo depadé mal?",
  ui_story_5008_50080901_5_dialog_content = "Está bien, coo... Permítanme usar mi técnica de reparación patentada \"Coo Coo Ca Choo\".",
  ui_story_5008_50080901_6_dialog_content = "<anim type=Shake><size=45>¡No lo golpees! ¡Deja de destrozarlo!</size></anim>",
  ui_story_5008_50080901_7_dialog_content = "¡Creo que la lámpara se ve peor después de que la aplastaste!",
  ui_story_5008_50080901_8_dialog_content = "No hay botones ni interruptores en el exterior de esta lámpara...",
  ui_story_5008_50080901_9_dialog_content = "¿Quizás utiliza la activación temporizada automática?",
  ui_story_5008_50080901_10_dialog_content = "Hmm... ¿No es hora de encender las luces?",
  ui_story_5008_50080901_11_dialog_content = "Supongo que sí...",
  ui_story_5008_50080901_12_dialog_content = "Puede que haya algún problema con el contacto.",
  ui_story_5008_50080901_13_dialog_content = "O tal vez sea otra cosa...",
  ui_story_5008_50080901_14_dialog_content = "¿Quizás el interruptor de la luz no está controlado por un circuito mecánico, sino por algún tipo de tecnología Celestita?",
  ui_story_5008_50080901_15_dialog_content = "¿No estás seguro, Naroxel?",
  ui_story_5008_50080901_16_dialog_content = "Lo siento, no lo sé con certeza.",
  ui_story_5008_50080901_17_dialog_content = "Primero puede manejar la siguiente tarea. Déjame pensar en cómo podemos hacer que esta lámpara de pared se ilumine...",
  ui_story_5008_50080901_18_dialog_content = "¡Naroxel se ve aún más hermosa cuando piensa mucho!",
  ui_story_5008_50080901_19_dialog_content = "Si alguna vez quieres crecer, pasa más tiempo trabajando y menos mirando boquiabierto.",
  ui_story_5008_50080901_20_dialog_content = "¿¡Eh!? ¡Tú eres quien necesita trabajar más, Dove!",
  ui_story_5008_50080901_21_dialog_content = "¡Coo, coo! Solo te estoy diciendo cómo puedes crecer.",
  ui_story_5008_50080901_22_dialog_content = "Oh... ¿En sedio?",
  ui_story_5008_50080901_23_dialog_content = "Pero has estado ahí tidado por tanto tiempo...",
  ui_story_5008_50080901_24_dialog_content = "¡Tú también debedías creced!",
  ui_story_5008_50080901_25_dialog_content = "¡Ya soy mayor!",
  ui_story_5008_50081001_1_dialog_content = "¡Repadé esta sillita!",
  ui_story_5008_50081001_2_dialog_content = "¿Quizás los clientes hiciedon sus pedidos aquí...?",
  ui_story_5008_50081001_3_dialog_content = "Dove, ¿te gustaría sed la decepcionista de la oficina de correos?",
  ui_story_5008_50081001_4_dialog_content = "Claro que sí. Hola, coo, ¿en qué puedo ayudarte?",
  ui_story_5008_50081001_5_dialog_content = "¡Eso fue rápido!",
  ui_story_5008_50081001_6_dialog_content = "Pero no te pareces en nada a un celestita...",
  ui_story_5008_50081001_7_dialog_content = "Así que... ¿Cómo debe comportarse una recepcionista Celestita?",
  ui_story_5008_50081001_8_dialog_content = "Bien... ¡Creo que primero deberías hacer tu diadema en blanco y negro!",
  ui_story_5008_50081001_9_dialog_content = "Entonces, ¿debería comenzar inspeccionando la oficina de correos como lo haría el Navegador?",
  ui_story_5008_50081001_10_dialog_content = "Pobablemente...",
  ui_story_5008_50081001_11_dialog_content = "¿Estás dista, Dove? ¡Quiero haced un pedido!",
  ui_story_5008_50081001_12_dialog_content = "¿Qué le gustaría enviar hoy?",
  ui_story_5008_50081001_13_dialog_content = "Envía... Uh, quiero enviar dos dequeñas bolas de nieve.",
  ui_story_5008_50081001_14_dialog_content = "¿¡Coo!? ¡Señorita, su bola de nieve se derretirá antes de que llegue!",
  ui_story_5008_50081001_15_dialog_content = "¿No estamos jugando a los doles? ¡Tienes que fingid que la bola de nieve no se dedite!",
  ui_story_5008_50081001_16_dialog_content = "Coo...",
  ui_story_5008_50081001_17_dialog_content = "Una bola de nieve. Ya veo, coo. ¿A dónde le gustaría enviarlo, señorita?",
  ui_story_5008_50081001_18_dialog_content = "Envíalo a Dumopolis, ¡a Naroxel!",
  ui_story_5008_50081001_19_dialog_content = "¡Entonces Naroxel pensará en mí en cuanto vea mi pequeña bola de nieve!",
  ui_story_5008_50081001_20_dialog_content = "¿Lumopolis, eh? Coo, eso será... ¡100,000 Nightium!",
  ui_story_5008_50081001_21_dialog_content = "¿¡Qué!? ¿¡Por qué es tan cado aquí!?",
  ui_story_5008_50081001_22_dialog_content = "Porque cada vez que voy a Lumopolis a entregar cartas, ¡navegar por la ciudad siempre requiere mucho tiempo y esfuerzo!",
  ui_story_5008_50081001_23_dialog_content = "Todo esto se ha incluido en el costo, señorita.",
  ui_story_5008_50081001_24_dialog_content = "¡Entonces debo dárselo yo mismo a Naroxel!",
  ui_story_5008_50081001_25_dialog_content = "¿Ah? ¿Qué está pasando?",
  ui_story_5008_50081001_26_dialog_content = "¡Naroxel! ¡Has vuelto! ¡Tengo una pequeña boda de nieve para ti!",
  ui_story_5008_50081001_27_dialog_content = "Gracias, Tweety.",
  ui_story_5008_50081001_28_dialog_content = "Pero si sostengo esta bola de nieve en mi mano, se convertirá en agua en poco tiempo.",
  ui_story_5008_50081001_29_dialog_content = "Eso es lo que dije, ¡coo!",
  ui_story_5008_50081101_1_dialog_content = "¡Dong!",
  ui_story_5008_50081101_2_dialog_content = "¡El deloj está funcionando!",
  ui_story_5008_50081101_3_dialog_content = "Fantástico, Tweety.",
  ui_story_5008_50081101_4_dialog_content = "¿Me pregunto si usaron esto para rastrear sus horas de trabajo...?",
  ui_story_5008_50081101_5_dialog_content = "Hmm... ¡Creo que tenían una forma más avanzada de hacerlo!",
  ui_story_5008_50081101_6_dialog_content = "¿Una forma más avanzada?",
  ui_story_5008_50081101_7_dialog_content = "¡Ciedto! ¿No todos los Celestitas tienen habididades psíquicas?",
  ui_story_5008_50081101_8_dialog_content = "¡Todo lo que necesitan hacer es echar un vistazo para saber cuán mal hemos estado trabajando hoy!",
  ui_story_5008_50081101_9_dialog_content = "¡Eso es demasiado!",
  ui_story_5008_50081101_10_dialog_content = "¡No te asustes, Dove!",
  ui_story_5008_50081101_11_dialog_content = "Si fuera celestita, supongo que dodmir es parte de tu trabajo.",
  ui_story_5008_50081101_12_dialog_content = "¡Eso quisiera!",
  ui_story_5008_50081101_13_dialog_content = "Si los celestitas pensaban que mi trabajo era dormir...",
  ui_story_5008_50081101_14_dialog_content = "¡Sería empleado del año! ¡Coo!",
  ui_story_5008_50081101_15_dialog_content = "¡Y estoy seguro de que obtendría un aumento!",
  ui_story_5008_50081101_16_dialog_content = "¡Pero tu trabajo es ser un buen mensajedo!",
  ui_story_5008_50081101_17_dialog_content = "¿No puedes dejarme soñar por un momento?",
  ui_story_5008_50081101_18_dialog_content = "¡Todos deberían tener un sueño!",
  ui_story_5008_50081101_19_dialog_content = "Dove, el reloj ha sido reparado.",
  ui_story_5008_50081101_20_dialog_content = "¿Hmm? Lo se. Está contando mis horas de trabajo ...",
  ui_story_5008_50081101_21_dialog_content = "Me gustaría recordarte que, ahora que podemos ver el tiempo, puedo decir con seguridad que acabas de perder media hora.",
  ui_story_5008_50081101_22_dialog_content = "¡Coo! Fueron solo veintiséis minutos... ¡Veintiséis minutos!",
  ui_story_5008_50081101_23_dialog_content = "¡El tic-tac del reloj suena muy bien!",
  ui_story_5008_50081101_24_dialog_content = "De verdad...",
  ui_story_5008_50081101_25_dialog_content = "Es como si su tictac anunciara que el tiempo, estancado en Eraveil durante tanto tiempo, ahora fluye una vez más.",
  ui_story_5008_50081201_1_dialog_content = "Entonces, así es como funciona...",
  ui_story_5008_50081201_2_dialog_content = "No debería haber esperado menos de la oficina de correos de Eraveil.",
  ui_story_5008_50081201_3_dialog_content = "¡Coo! ¡Deberíamos tomar nota de cómo funciona este sistema!",
  ui_story_5008_50081201_4_dialog_content = "Pongamos algunas bolas de nieve en la cinta transportadora...",
  ui_story_5008_50081201_5_dialog_content = "¡Wow! ¡Las luciérnagas levantaron la pequeña bola de nieve!",
  ui_story_5008_50081201_6_dialog_content = "¿Crees que pueden llevar cosas pesadas?",
  ui_story_5008_50081201_7_dialog_content = "No lo sé...",
  ui_story_5008_50081201_8_dialog_content = "Pero puedo intentadlo-",
  ui_story_5008_50081201_9_dialog_content = "¿Coo, coo? ¡Agáchate, Tweety!",
  ui_story_5008_50081201_10_dialog_content = "¡No te asustes, Dove!",
  ui_story_5008_50081201_11_dialog_content = "Incluso si las luciédnagas me llevan afueda, ¡puedo volar de degreso!",
  ui_story_5008_50081201_12_dialog_content = "Eso no es lo que me preocupa!",
  ui_story_5008_50081201_13_dialog_content = "¡Solo me preocupa no poder caminar derecho después de haber sido golpeado por tantas bolas de nieve!",
  ui_story_5008_50081201_14_dialog_content = "¿Oh? ¿De qué bolas de nieve estás hablando?",
  ui_story_5008_50081201_15_dialog_content = "Antes de saltar allí, las luciérnagas llevaban tus bolas de nieve.",
  ui_story_5008_50081201_16_dialog_content = "Luego te subiste a la cinta transportadora...",
  ui_story_5008_50081201_17_dialog_content = "Toda la oficina de correos tembló porque no podía soportar tu peso...",
  ui_story_5008_50081201_18_dialog_content = "¡Entonces las bolas de nieve que llevaban las luciérnagas me golpearon en la cabeza!",
  ui_story_5008_50081201_19_dialog_content = "¡Oh, lo siento, Dove! ¡Bajaré ahora!",
  ui_story_5008_50081201_20_dialog_content = "¡Solo baja ahora mismo! ¡No saltes sobre la cinta transportadora!",
  ui_story_5008_50081201_21_dialog_content = "¡Eyyup! ¡Acepto!",
  ui_story_5008_50081201_22_dialog_content = "¿Cuánto pesas?",
  ui_story_5008_50081201_23_dialog_content = "Hey...",
  ui_story_5008_50081201_24_dialog_content = "¡Dove, mira! ¡Las luciérnagas llevaron las bolas de nieve afuera!",
  ui_story_5008_50081201_25_dialog_content = "¡Acabo de ayudadte a revisar la estructuda de la cinta transportadora de duciérnagas!",
  ui_story_5008_50081201_26_dialog_content = "¿Hmm? Cuéntame sobre eso...",
  ui_story_5008_50081201_27_dialog_content = "Voy a esbozar el sistema y llevárselo a Vice. Ella puede ayudarme a hacer un dibujo mecánico más detallado...",
  ui_story_5008_50081201_28_dialog_content = "Este es realmente un sistema muy avanzado.",
  ui_story_5008_50081201_29_dialog_content = "Si podemos instalarlo en nuestras otras sucursales, el trabajo será mucho más fácil para nuestros pequeños mensajeros.",
  ui_story_5008_50081201_30_dialog_content = "Y muestra que los celestitas estaban verdaderamente adelantados a su tiempo...",
  ui_story_5008_50081201_31_dialog_content = "Después de todo, esta oficina de correos estuvo operativa hace diecisiete años.",
  ui_story_5008_50081301_1_dialog_content = "Esto es... ¡Este es un estante para postales!",
  ui_story_5008_50081301_2_dialog_content = "¡Wow! ¡Déjame midad! ¡Déjame midad!",
  ui_story_5008_50081301_3_dialog_content = "¿Estas son postales de hace diecisiete años?",
  ui_story_5008_50081301_4_dialog_content = "Probablemente, ¿coo?",
  ui_story_5008_50081301_5_dialog_content = "Vi un letrero de Illumina en el reverso de esta postal.",
  ui_story_5008_50081301_6_dialog_content = "Su ropa se ve un poco diferente a la que usa Illumina ahora... Deben ser uniformes de entonces.",
  ui_story_5008_50081301_7_dialog_content = "Mira, esta postal de Northland tiene una foto de Su Majestad.",
  ui_story_5008_50081301_8_dialog_content = "¿Incluso tienen postales de Northland?",
  ui_story_5008_50081301_9_dialog_content = "¡Entonces déjame despertar por una postal de Montaña Nube!",
  ui_story_5008_50081301_10_dialog_content = "Tweety, por supuesto que hay postales de Northland. Todo el mundo conoce Northland...",
  ui_story_5008_50081301_11_dialog_content = "Pero antes de conocerte, nunca había oído hablar de Montaña Nube.",
  ui_story_5008_50081301_12_dialog_content = "Dove, supongo que no te llevas muy bien con Hiiro...",
  ui_story_5008_50081301_13_dialog_content = "Vamos... ¿Quién realmente quiere acercarse al Comandante de la Legión...?",
  ui_story_5008_50081301_14_dialog_content = "¿No le facilitaría eso saber si te has saltado el trabajo?",
  ui_story_5008_50081301_15_dialog_content = "¡Cada vez que me relajo, tengo que callarme cuando veo al Comandante Hiiro!",
  ui_story_5008_50081301_16_dialog_content = "Dove, ¡debes ser una holgazana profesional!",
  ui_story_5008_50081301_17_dialog_content = "¡Parece que hay caminos de personas de las que debes esconderte en la sucursal de Illumina!",
  ui_story_5008_50081301_18_dialog_content = "No estoy seguro de si holgazanear es realmente una cuestión de habilidad...",
  ui_story_5008_50081301_19_dialog_content = "Dove, estoy parado aquí mismo.",
  ui_story_5008_50081301_20_dialog_content = "N-Naroxel... ¡Yo-yo-solo estaba bromeando!",
  ui_story_5008_50081301_21_dialog_content = "¡No pude encontrar una postal de Montaña Nube!",
  ui_story_5008_50081301_22_dialog_content = "Probablemente se deba a que Montaña Nube está tan bien escondido. Puede que los celestitas ni siquiera supieran cómo ponerse en contacto contigo.",
  ui_story_5008_50081301_23_dialog_content = "Hmm... ¡Probablemente tengas razón!",
  ui_story_5008_50081301_24_dialog_content = "No hay tantas postales de Eraveil en este estante...",
  ui_story_5008_50081301_25_dialog_content = "Si tenemos la oportunidad... podemos encontrar un comerciante en Umbraton y pedir algunas postales nuevas de Eraveil.",
  ui_story_5008_50081301_26_dialog_content = "¿De verdad, Naroxel?",
  ui_story_5008_50081301_27_dialog_content = "Por supuesto. Después de todo, el Eraveil de hoy es diferente del Eraveil del pasado, que se muestra en esas postales antiguas.",
  ui_story_5008_50081401_1_dialog_content = "¡Uh-huh! ¡Este pequeño cojín ahora es tan suave y cómodo!",
  ui_story_5008_50081401_2_dialog_content = "¡Coo! Tweety, mira hacia allá ...",
  ui_story_5008_50081401_3_dialog_content = "¡Wow! ¡Naroxel, Dove! ¡Mida! ¡Es un gatito!",
  ui_story_5008_50081401_4_dialog_content = "¡Aquí gatito-gatito!",
  ui_story_5008_50081401_5_dialog_content = "Gatito... ¿Gatito?",
  ui_story_5008_50081401_6_dialog_content = "¿Gatito? ¿Qué es eso?",
  ui_story_5008_50081401_7_dialog_content = "Eso es lo que solemos llamar gatos. ¿Qué es un gatito-gatito?",
  ui_story_5008_50081401_8_dialog_content = "Hmm... Gatito-gatito es lo que decimos en Montaña Nube...",
  ui_story_5008_50081401_9_dialog_content = "¿Qué tal si se nos ocurre un nombre juntos?",
  ui_story_5008_50081401_10_dialog_content = "Encontrar un nombre es difícil... Adelante, piensa en uno.",
  ui_story_5008_50081401_11_dialog_content = "¡Lo sé! ¿Qué tal \"Tiernito\"?",
  ui_story_5008_50081401_12_dialog_content = "¡Porque es tan lindo y tierno!",
  ui_story_5008_50081401_13_dialog_content = "Eso es tan básico... ¡Este es un gato de Eraveil!",
  ui_story_5008_50081401_14_dialog_content = "¿No debería ser algo más único... como \"Era\" o algo así?",
  ui_story_5008_50081401_15_dialog_content = "Intenta destrozar tu pequeño cerebro de nuevo.",
  ui_story_5008_50081401_16_dialog_content = "Ah... ¿Qué tal \"Bola de nieve\"?",
  ui_story_5008_50081401_17_dialog_content = "Lo estás nombrando en función de las cosas que te gustan, ¿no es así?",
  ui_story_5008_50081401_18_dialog_content = "¿Pero no crees que se despierta como una pelota?",
  ui_story_5008_50081401_19_dialog_content = "O podríamos llamarlo \"Dormilón\"...",
  ui_story_5008_50081401_20_dialog_content = "A los gatos les encanta dormir...",
  ui_story_5008_50081401_21_dialog_content = "¡Sí, pero no tanto como a ti te encanta dormir, Dove!",
  ui_story_5008_50081401_22_dialog_content = "Me atrapaste.",
  ui_story_5008_50081401_23_dialog_content = "Bueno, dado que los gatos siempre actúan tan bien, deberíamos llamarlo...",
  ui_story_5008_50081401_24_dialog_content = "Coo-Coo.",
  ui_story_5008_50081401_25_dialog_content = "¡Eso no tiene ningún sentido, Dove!",
  ui_story_5008_50081401_26_dialog_content = "¡Y es un gato, no una paloma!",
  ui_story_5008_50081401_27_dialog_content = "¡Tú eres la paloma! Tu... ¡paloma! No... Eres una especie completamente nueva: ¡el pipsqueak balbuceante!",
  ui_story_5008_50081401_28_dialog_content = "Pensé que ustedes dos eran demasiado mayores para discutir así...",
  ui_story_5008_50081401_29_dialog_content = "¡Naroxel, Tweety me llamó palomita primero! ¡Soy mucho más madura que ella!",
  ui_story_5008_50081401_30_dialog_content = "¡No! No me pareces maduro... ¡pero ciertamente te ves perezosa!",
  ui_story_5008_50081401_31_dialog_content = "Tweety, todavía eres joven. Hay muchas cosas que aún no comprendes.",
  ui_story_5008_50081401_32_dialog_content = "Ven ahora. Si sigues discutiendo, asustarás al gato.",
  ui_story_5008_50081401_33_dialog_content = "Los gatos salvajes han logrado sobrevivir en un lugar tan peligroso y desolado...",
  ui_story_5008_50081401_34_dialog_content = "De hecho, el poder de la naturaleza nunca debe subestimarse. Me pregunto si encontraremos a sus amigos o algún otro animal pequeño cerca.",
  ui_story_5008_50081401_35_dialog_content = "¡Naroxel! ¿Por qué no le das un nombre al gatito?",
  ui_story_5008_50081401_36_dialog_content = "Hmm... No soy muy bueno para nombrar cosas.",
  ui_story_5008_50081401_37_dialog_content = "¡Pero los nombres de tus dos pájaros son muy buenos!",
  ui_story_5008_50081401_38_dialog_content = "Gracias, Tweety.",
  ui_story_5008_50081401_39_dialog_content = "Pero no todas las almas necesitan un nombre. Después de todo, es solo un código.",
  ui_story_5008_50081401_40_dialog_content = "Mientras esté lleno de amor, incluso \"gatito-gatito\" es un hermoso apodo, ¿no es así?",
  ui_story_5008_50081501_1_dialog_content = "Ambas han trabajado muy duro.",
  ui_story_5008_50081501_2_dialog_content = "La oficina de correos de Eraveil está ahora en buen estado.",
  ui_story_5008_50081501_3_dialog_content = "No solo está en orden, ahora se siente como un lugar de trabajo real...",
  ui_story_5008_50081501_4_dialog_content = "Estanterías, un reloj, postales...",
  ui_story_5008_50081501_5_dialog_content = "La mayor parte es equipo Unión de Mensajería estándar...",
  ui_story_5008_50081501_6_dialog_content = "¡Pero no hay gatitos en la sucursal de Illumina!",
  ui_story_5008_50081501_7_dialog_content = "¡Coo, pero tenemos a Philyshy!",
  ui_story_5008_50081501_8_dialog_content = "Muy bien Dove, Tweety.",
  ui_story_5008_50081501_9_dialog_content = "Nuestra misión sigue siendo la misma. El equipo de la oficina de correos debe estar unificado.",
  ui_story_5008_50081501_10_dialog_content = "Especialmente aquí...",
  ui_story_5008_50081501_11_dialog_content = "Después de diecisiete años de silencio, la oficina de correos volverá a abrir sus puertas.",
  ui_story_5008_50081501_12_dialog_content = "¡Naroxel!",
  ui_story_5008_50081501_13_dialog_content = "¿Se puede entregar aquí ahora el correo atrasado de Umbraton?",
  ui_story_5008_50081501_14_dialog_content = "Bueno... Todo eso depende de si PlayerName firma con nosotros.",
  ui_story_5008_50081501_15_dialog_content = "Una vez que firme, se convertirá en el destinatario del correo de Eraveil.",
  ui_story_5008_50081501_16_dialog_content = "Espero que le vaya bien... y que pueda volver aquí sano y salvo.",
  ui_story_5008_50081501_17_dialog_content = "La Oficina de Correos de Eraveil, restaurada... El celestita presenciará personalmente esta escena.",
  ui_story_5008_50081501_18_dialog_content = "¡Increíble! ¡Coo!",
  ui_story_5008_50081501_19_dialog_content = "Entonces, Naroxel... ¿Finalmente hemos terminado aquí?",
  ui_story_5008_50081501_20_dialog_content = "Ya que tenemos que esperar PlayerName para volver, ¿puedo ir a dormir?",
  ui_story_5008_50081501_21_dialog_content = "¡Dove fidalmente encontró una dazón para dodmir!",
  ui_story_5008_50081501_22_dialog_content = "Casi lo olvido... Hoy es en realidad un festival especial para los Celestitas: Windelion.",
  ui_story_5008_50081501_23_dialog_content = "Windedion...",
  ui_story_5008_50081501_A1_dialog_content = "PlayerName mencionó Windewion, ¡pero todavía no estoy seguro de qué se trata el festival!",
  ui_story_5008_50081501_24_dialog_content = "solo creo PlayerName conoce los detalles de las costumbres del festival.",
  ui_story_5008_50081501_25_dialog_content = "Sin embargo, dado que es un festival, podemos asumir que hay decoraciones, comida y reuniones.",
  ui_story_5008_50081501_26_dialog_content = "Aunque la oficina de correos está operativa... Todavía parece un poco estéril.",
  ui_story_5008_50081501_27_dialog_content = "La oficina de correos ya está en funcionamiento.",
  ui_story_5008_50081501_28_dialog_content = "Tal vez... ¿podemos decorar este lugar juntos?",
  ui_story_5008_50081501_29_dialog_content = "¡Hagámoslo!",
  ui_story_5008_50081501_30_dialog_content = "Para cuando terminemos de desovar, PlayerName debería estar de vuelta!",
  ui_story_5008_50081501_31_dialog_content = "¡Se sorprenderá mucho cuando vea las decodaciones para el festival!",
  ui_story_5008_50081501_32_dialog_content = "Yo también lo creo. Simplemente no sé en qué estilo deberían estar las decoraciones de Windelion.",
  ui_story_5008_50081501_33_dialog_content = "¡Creo que deberíamos ignorar el estilo por ahora!",
  ui_story_5008_50081501_34_dialog_content = "Coo... Siempre que tengamos cuidado, debería estar bien.",
  ui_story_5008_50081501_35_dialog_content = "¡Wow! ¿Dove sabe tener cuidado?",
  ui_story_5008_50081501_36_dialog_content = "Bien, PlayerName me salvó una vez...",
  ui_story_5008_50081501_37_dialog_content = "Entonces, no me importa decorar este lugar para él.",
  ui_story_5008_50081501_38_dialog_content = "Hagamos nuestro mejor esfuerzo.",
  ui_story_5008_50081501_39_dialog_content = "Como no sabemos cómo les va... Solo podemos hacer nuestro mejor esfuerzo para ocuparnos del asunto en cuestión.",
  ui_story_5008_50081501_40_dialog_content = "Pero aquí no hay muchas cosas que podamos usar como decoración...",
  ui_story_5008_50081501_41_dialog_content = "Hmm... Decoramos la oficina de codeos de Montaña Nube con flodes de cedezo. ¿Qué debemos usar aquí?",
  ui_story_5008_50081501_42_dialog_content = "Puedo ponerme en contacto la unión y pedirles que envíen un lote de materiales de decoración de inmediato.",
  ui_story_5008_50081501_43_dialog_content = "Además, parece que finalmente he descubierto algo sobre la tecnología Celestita. Quizás podamos usarlo para alegrar este lugar.",
  ui_story_5008_50081501_44_dialog_content = "Naroxel... ¡Eres tan increíble!",
  ui_story_5008_50081501_45_dialog_content = "Y puedo intentar reciclar parte de la basura que acabamos de limpiar y usarla, coo...",
  ui_story_5008_50081501_46_dialog_content = "Puedo utilizar algunas de las habilidades que aprendí en Illumina.",
  ui_story_5008_50081501_47_dialog_content = "Todo el mundo parece dispuesto a trabajar... Incluso Dove.",
  ui_story_5008_50081501_48_dialog_content = "Así que... ¿Qué tal si les doy algunos bocadillos de la unión como recompensa?",
  ui_story_5008_50081501_49_dialog_content = "<size=50>N-No gracias!!!</size>",
  ui_story_5008_50081601_1_dialog_content = "¡Coo! Este patrón iluminado... Siento que lo he visto antes. Parece familiar...",
  ui_story_5008_50081601_2_dialog_content = "¡Oh! ¿Es este algún tipo de patrón de rama de Idumina?",
  ui_story_5008_50081601_3_dialog_content = "¡No he visto nada como esto en la sucudsal de Nodthland!",
  ui_story_5008_50081601_4_dialog_content = "No es un patrón de Illumina... Déjame ver...",
  ui_story_5008_50081601_5_dialog_content = "¡Coo! ¡Es del Colossus!",
  ui_story_5008_50081601_6_dialog_content = "¡Es exactamente igual que el del Colossus!",
  ui_story_5008_50081601_7_dialog_content = "Pero no está conectado a ningún tipo de circuito. No sé qué lo hace brillar.",
  ui_story_5008_50081601_8_dialog_content = "¿Quieres decir... está brillando pod sí solo?",
  ui_story_5008_50081601_9_dialog_content = "No está... saliendo.",
  ui_story_5008_50081601_10_dialog_content = "No pasa nada cuando lo pincho.",
  ui_story_5008_50081601_11_dialog_content = "Coo... Supongo que no es el patrón en sí lo que brilla.",
  ui_story_5008_50081601_12_dialog_content = "Es el material que usaron para dibujar las líneas. ¡Contiene una especie de sustancia luminosa!",
  ui_story_5008_50081601_13_dialog_content = "Entonces, usaron materiales que contenían una sustancia luminiscente para construir la oficina de correos... ¿y el Colossus?",
  ui_story_5008_50081601_14_dialog_content = "¿Por eso está brillando aquí?",
  ui_story_5008_50081601_15_dialog_content = "Yo tampoco lo sé...",
  ui_story_5008_50081601_16_dialog_content = "¡Pero te veías tan genial cuando te pusiste todo serio ahora!",
  ui_story_5008_50081601_17_dialog_content = "¡De repente me diste una probada de la genialidad de Illumina!",
  ui_story_5008_50081601_18_dialog_content = "Puedo sentir que esto no es un producto de la naturaleza.",
  ui_story_5008_50081601_19_dialog_content = "El material luminoso en el patrón debe haber sido fabricado con tecnología Celestita única.",
  ui_story_5008_50081601_20_dialog_content = "Sin embargo, parece que nadie sabe por qué brilla.",
  ui_story_5008_50081601_21_dialog_content = "Ya veo... No es de extrañar que solo lo haya visto en el Colossus y aquí.",
  ui_story_5008_50081601_22_dialog_content = "¡Ok! ¡Ahora el acedtijo está resuelto!",
  ui_story_5008_50081601_23_dialog_content = "¡Dibujémosdlo!",
  ui_story_5008_50081601_24_dialog_content = "¡Este dugar está tan vacío! ¡Necesitamos llenarlo con un poco de espíditu davideño!",
  ui_story_5008_50081601_25_dialog_content = "Coo... No puedo dibujar...",
  ui_story_5008_50081601_26_dialog_content = "¿Te preocupa que me día de tu dibujo?",
  ui_story_5008_50081601_27_dialog_content = "¡No te dreocupes, Dove! ¡Ni siquiera me deí de los dibujos de Vice!",
  ui_story_5008_50081601_28_dialog_content = "¿Cómo te atreves a comparar mis habilidades de dibujo con las de Vice? ¡Coo, coo!",
  ui_story_5008_50081601_29_dialog_content = "¿Quieres decir que edes mejor dibujando que Vice?",
  ui_story_5008_50081601_30_dialog_content = "¡Claro que lo soy!",
  ui_story_5008_50081701_1_dialog_content = "Este buzón de autoservicio parece pertenecer al Colossus.",
  ui_story_5008_50081701_2_dialog_content = "¡Ah, un buzón! ¡Quiero enviarme una postal!",
  ui_story_5008_50081701_3_dialog_content = "¡Nunca he recibido una postal de Eraveil!",
  ui_story_5008_50081701_4_dialog_content = "Entonces te enviaré uno también... Coo.",
  ui_story_5008_50081701_5_dialog_content = "¿Qué escribirás en tu postal?",
  ui_story_5008_50081701_6_dialog_content = "Creo que escribiré \"¡Un día de vacaciones pagadas en la cama nunca es un día en vano!\".",
  ui_story_5008_50081701_7_dialog_content = "Coo... Enviada.",
  ui_story_5008_50081701_8_dialog_content = "Ah, ¿qué escribir, qué escribir?",
  ui_story_5008_50081701_9_dialog_content = "¡Espero poder ser tan intedigente y hedmoso como Naroxel!",
  ui_story_5008_50081701_10_dialog_content = "Cometiste un... error de ortografía.",
  ui_story_5008_50081701_12_dialog_content = "Inteligente no tiene una \"d\".",
  ui_story_5008_50081701_13_dialog_content = "Voy a bodar esa \"d\"... ¡Bien, hecho!",
  ui_story_5008_50081701_14_dialog_content = "Cuando PlayerName regresa para firmar el contrato, ¡la publicación volverá a funcionar!",
  ui_story_5008_50081701_15_dialog_content = "Luego, cuando vuelva a Montaña Nube, ¡recibiré esta postal de Eraveil!",
  ui_story_5008_50081701_16_dialog_content = "Bueno, siempre y cuando mi postal no sea enviada por un mensajero como Dove.",
  ui_story_5008_50081701_17_dialog_content = "¿¡Coo, coo!?",
  ui_story_5008_50081701_18_dialog_content = "¿Qué estás haciendo en cuclillas de repente?",
  ui_story_5008_50081701_19_dialog_content = "¡Quiero ver cuántas cartas no enviadas hay en este buzón!",
  ui_story_5008_50081701_20_dialog_content = "Eso tiene sentido. Déjame verlo también.",
  ui_story_5008_50081701_21_dialog_content = "¡Dove, tu manta me está apretando!",
  ui_story_5008_50081701_22_dialog_content = "Parece que hay muchas cartas que no se han enviado...",
  ui_story_5008_50081701_23_dialog_content = "Qué pena. Me pregunto a qué mensajero se le asignarán estas cartas...",
  ui_story_5008_50081701_24_dialog_content = "Me alegro de que no sea yo.",
  ui_story_5008_50081701_25_dialog_content = "¡Encontré algo! ¡Esta cadta tiene flodes de cedezo por todas partes! ¿Es una carta a Montaña Nube?",
  ui_story_5008_50081701_26_dialog_content = "¿Son esas flores de cerezo? Se ven rojas y la cantidad de pétalos parece extraña...",
  ui_story_5008_50081701_27_dialog_content = "¿Qué están haciendo ustedes dos frente al buzón?",
  ui_story_5008_50081701_28_dialog_content = "¡Oh! ¡Naroxel! ¡Estaba buscando en el buzón y creo que encontré una carta para Montaña Nube!",
  ui_story_5008_50081701_29_dialog_content = "¿Montaña Nube? Entonces, ¿Eraveil realmente había establecido contacto con Montaña Nube incluso en ese entonces? Pero no pudimos encontrar ninguna postal de Montaña Nube antes...",
  ui_story_5008_50081701_30_dialog_content = "Déjame confirmar. Ustedes dos-",
  ui_story_5008_50081701_31_dialog_content = "<size=45>¡¡¡Ay!!!</size>",
  ui_story_5008_50081701_32_dialog_content = "<size=45>¡Vaya!</size>",
  ui_story_5008_50081701_33_dialog_content = "Phwee... ¿Estás bien, Tweety? ¿Naroxel?",
  ui_story_5008_50081701_34_dialog_content = "Oh... Estoy bien. Simplemente no esperaba que te levantaras tan de repente...",
  ui_story_5008_50081701_35_dialog_content = "No esperaba que te inclinaras tan de repente... Ay...",
  ui_story_5008_50081701_36_dialog_content = "¿Tweety? ¿Tweety?",
  ui_story_5008_50081701_37_dialog_content = "<anim type=Shake>Vaya... puedo ver tres palomas y cuatro nawoxels...</anim>",
  ui_story_5008_50081801_1_dialog_content = "Jajaja...",
  ui_story_5008_50081801_2_dialog_content = "¡Naroxel se dió!",
  ui_story_5008_50081801_3_dialog_content = "¡diendo tan feliz!",
  ui_story_5008_50081801_4_dialog_content = "Sí, Tweety. Mira aquí.",
  ui_story_5008_50081801_5_dialog_content = "¿Ah? ¿Desde cuándo esta pequeña estatua tenía un sombrero en la cabeza?",
  ui_story_5008_50081801_6_dialog_content = "Jaja... Y un gracioso sombrero negro puntiagudo, además...",
  ui_story_5008_50081801_7_dialog_content = "Es completamente incongruente con la estatua en sí.",
  ui_story_5008_50081801_8_dialog_content = "Ahora el pequeño Colossus parece una muñeca divertida.",
  ui_story_5008_50081801_9_dialog_content = "¿Sabes si los Codossus necesitan comer?",
  ui_story_5008_50081801_10_dialog_content = "No lo sé, pero nunca he visto comer a Soroz.",
  ui_story_5008_50081801_11_dialog_content = "Pero no puedo comunicarme con él, así que nunca le pregunté si necesitaba comer...",
  ui_story_5008_50081801_12_dialog_content = "Tal vez el Colossus realmente necesite comer, pero ¿no lo hemos visto?",
  ui_story_5008_50081801_13_dialog_content = "¡Ah! ¡O tal vez Sodoz está a dieta!",
  ui_story_5008_50081801_14_dialog_content = "¡Conozco a muchas chicas en Montaña Nube que harían eso todo el tiempo!",
  ui_story_5008_50081801_15_dialog_content = "Erm... No creo que un Colossus tenga ese tipo de problemas...",
  ui_story_5008_50081801_16_dialog_content = "¡Pero todavía deberíamos poner algunos bocadillos de la unión cerca de la estatua!",
  ui_story_5008_50081801_17_dialog_content = "¿Y si el Codossus necesita comer?",
  ui_story_5008_50081801_18_dialog_content = "De esa manera...",
  ui_story_5008_50081801_19_dialog_content = "Después PlayerName regresa, se encargará de que coloquemos algo de comida cerca de la estatua del Cowossus...",
  ui_story_5008_50081801_20_dialog_content = "¡Eso defiditivamente lo haría feliz!",
  ui_story_5008_50081801_21_dialog_content = "Creo que podemos intentarlo.",
  ui_story_5008_50081801_22_dialog_content = "¿Nadoxel también lo cree? ¡Excedente!",
  ui_story_5008_50081801_23_dialog_content = "Podemos utilizar este sabor de bocadillos de unión.",
  ui_story_5008_50081801_24_dialog_content = "Tienen sabor a aceite.",
  ui_story_5008_50081801_25_dialog_content = "Qué pobre estatua...",
  ui_story_5008_50081801_26_dialog_content = "¡Excedente, eso es perfecto!",
  ui_story_5008_50081801_27_dialog_content = "¡Oh! ¡Naroxel, Dove! ¡Hay algo más!",
  ui_story_5008_50081801_28_dialog_content = "¡Creo que tengo un sombrero que se adapta más a la estatua que el que lleva ahoda!",
  ui_story_5008_50081801_29_dialog_content = "¿Hay un sombrero que le quede mejor que este puntiagudo?",
  ui_story_5008_50081801_30_dialog_content = "¿Qué tipo de sombrero es?",
  ui_story_5008_50081801_31_dialog_content = "¡Tada! Es mi propio pedsonal—",
  ui_story_5008_50081801_32_dialog_content = "¡Un gorro de baño!",
  ui_story_5008_50081801_33_dialog_content = "Oh... Ya veo...",
  ui_story_5008_50081801_34_dialog_content = "Bien entonces. Dove, ¿hay algún lugar que todavía necesite decoración?",
  ui_story_5008_50081801_35_dialog_content = "Revisaré los materiales que recopilé nuevamente.",
  ui_story_5008_50081801_36_dialog_content = "Recuerdo que había unas velas pequeñas allí hace un momento. Iré a buscarlos contigo.",
  ui_story_5008_50081801_37_dialog_content = "¡Naroxel! ¡Dove! ¡No me dejes detrás!",
  ui_story_5008_50081801_38_dialog_content = "¡Dale otra oportunidad al gorro de baño!",
  ui_story_5008_50081801_39_dialog_content = "¡Creo que es perfecto para esta pequeña estatua!",
  ui_story_5008_50081901_A1_dialog_content = "<color=#e8d9bb>♪</color>",
  ui_story_5008_50081901_1_dialog_content = "Naroxel, eres una cantante maravillosa...",
  ui_story_5008_50081901_2_dialog_content = "Gracias, Tweety.",
  ui_story_5008_50081901_3_dialog_content = "¿Cuál era esa canción que estabas cantando? ¿Puedes enseñarme?",
  ui_story_5008_50081901_4_dialog_content = "Coo, es realmente una linda canción.",
  ui_story_5008_50081901_5_dialog_content = "Déjame enseñarte, Tweety. ¡Yo la escribí!",
  ui_story_5008_50081901_6_dialog_content = "<size=45><anim type=Shake>Cuu, cuu... Cuu, cuu, cuu, cuu! ¡Cuu, cuu, cuu, cuu, cuu!</anim></size>",
  ui_story_5008_50081901_7_dialog_content = "Dove, ¿fue eso dealmente... cantar?",
  ui_story_5008_50081901_8_dialog_content = "¿Suena como do que estabas diciendo antes mientras dodmías?",
  ui_story_5008_50081901_9_dialog_content = "¡Solo escucha la melodía! ¡No te concentres en las palabras!",
  ui_story_5008_50081901_10_dialog_content = "En realidad, esta es una canción que aprendí en el bosque.",
  ui_story_5008_50081901_11_dialog_content = "Te lo cantaré de nuevo, Tweety.",
  ui_story_5008_50081901_12_dialog_content = "Naroxel...",
  ui_story_5008_50081901_13_dialog_content = "Cuando cantas, parece que incluso tus luciédnagas están meciéndose con el ditmo...",
  ui_story_5008_50081901_14_dialog_content = "Yo también vi eso... ¿Entienden tu canción?",
  ui_story_5008_50081901_15_dialog_content = "¿Les dusta mucho tu canto?",
  ui_story_5008_50081901_16_dialog_content = "¡Déjame intentadlo!",
  ui_story_5008_50081901_17_dialog_content = "<size=45><anim type=Shake>¡Guau, wawawa! Wawawa, wawa!</anim></size>",
  ui_story_5008_50081901_18_dialog_content = "No se mueven en lo más mínimo.",
  ui_story_5008_50081901_19_dialog_content = "¿Ah? Tampoco se movieron cuando Dove estaba cantando hace un momento.",
  ui_story_5008_50081901_20_dialog_content = "Quizás... nuestro canto les suena a ruido.",
  ui_story_5008_50081901_21_dialog_content = "Entonces, ¿esas luciédnagas solo reconocen la voz de Naroxel como un canto deal?",
  ui_story_5008_50081901_22_dialog_content = "Es triste decirlo, pero creo que eso es lo que está pasando aquí...",
  ui_story_5008_50081901_23_dialog_content = "Sin embargo, las luciérnagas del Colossus pueden hablarnos a su manera sencilla, pero las luciérnagas de aquí no parecen ser capaces de hacerlo.",
  ui_story_5008_50081901_24_dialog_content = "Pero se mueven al ritmo de mi canción... Lo que prueba que no son meras máquinas.",
  ui_story_5008_50081901_25_dialog_content = "¿No son las luciérnagas también una maravillosa creación de la naturaleza?",
  ui_story_5008_50081901_26_dialog_content = "¿Podrían ser una creación mágica de Eraveil?",
  ui_story_5008_50081901_27_dialog_content = "tal vez puedas preguntar PlayerName Cuando el regrese.",
  ui_story_5008_50081901_28_dialog_content = "Me pregunto si las luciérnagas del Colossus también bailarán con mi canción...",
  ui_story_5008_50082001_1_dialog_content = "De aquí... Eraveil se ve tan hermoso.",
  ui_story_5008_50082001_2_dialog_content = "Pero, ¿pada qué sirven estas pequeñas badandillas?",
  ui_story_5008_50082001_3_dialog_content = "Deberíamos echar un vistazo más de cedca al hedmoso paisaje.",
  ui_story_5008_50082001_4_dialog_content = "Esta ventana parece cerrada, pero aún puede sentir el viento que la atraviesa.",
  ui_story_5008_50082001_5_dialog_content = "Eso significa que se puede abrir.",
  ui_story_5008_50082001_6_dialog_content = "Por tanto, las barandillas sirven para evitar que las personas caigan por las ventanas.",
  ui_story_5008_50082001_7_dialog_content = "¡Coo! Mirando desde aquí, realmente parece bastante alto...",
  ui_story_5008_50082001_8_dialog_content = "Después de todo, esta oficina de correos está ubicada en la Torre Blanca.",
  ui_story_5008_50082001_9_dialog_content = "Escuché que algunos aurorians tienen miedo a las alturas...",
  ui_story_5008_50082001_10_dialog_content = "¿Ah? ¿En sedio?",
  ui_story_5008_50082001_11_dialog_content = "¿Cómo puede un mensajedo temer a las altudas?",
  ui_story_5008_50082001_12_dialog_content = "¿No crees que los aurorians que temen a las alturas deberían ser mensajeros?",
  ui_story_5008_50082001_13_dialog_content = "No es como si la gente estuviera haciendo cola para hacer un trabajo tan agotador... Coo...",
  ui_story_5008_50082001_14_dialog_content = "En términos generales, el sindicato probará a los candidatos por adelantado antes de convertirlos oficialmente en mensajeros.",
  ui_story_5008_50082001_15_dialog_content = "¿Hmm? Entonces, si tienes miedo a las alturas, ¿no pasarás la prueba?",
  ui_story_5008_50082001_16_dialog_content = "¿Entonces no puedes ser un mensajero?",
  ui_story_5008_50082001_17_dialog_content = "Sí. La unión también debe proteger la seguridad de cada mensajero.",
  ui_story_5008_50082001_18_dialog_content = "¿Qué se considera tener miedo a las alturas?",
  ui_story_5008_50082001_19_dialog_content = "Cuando se para en un lugar alto, al principio se siente mareado y, finalmente, se desmaya.",
  ui_story_5008_50082001_20_dialog_content = "Ya veo... Coo...",
  ui_story_5008_50082001_21_dialog_content = "¿Dove? ¿Dove?",
  ui_story_5008_50082001_22_dialog_content = "¡Naroxel, Dove se desmayó!",
  ui_story_5008_50082001_23_dialog_content = "Qué lástima...",
  ui_story_5008_50082001_24_dialog_content = "Dove, estuviste inconsciente durante dos minutos.",
  ui_story_5008_50082001_25_dialog_content = "Esos dos minutos deberán deducirse de su salario después de regresar a Illumina.",
  ui_story_5008_50082001_26_dialog_content = "¿¡Coo!? ¿¡Acaso tienes un corazón!?",
  ui_story_5008_50082001_27_dialog_content = "Porque yo sé, Dove, que no tienes miedo a las alturas.",
  ui_story_5008_50082001_28_dialog_content = "Siempre te duermes mientras vuelas, y a menudo terminas cayendo del cielo...",
  ui_story_5008_50082001_29_dialog_content = "Incluso he oído hablar de tus hazañas en Illumina, desde aquí.",
  ui_story_5008_50082001_30_dialog_content = "Coo...",
  ui_story_5008_50082101_1_dialog_content = "<size=45>Coo... Coo-achoo!</size>",
  ui_story_5008_50082101_2_dialog_content = "¡Dove! ¡Has vuedto!",
  ui_story_5008_50082101_3_dialog_content = "Ah... ¡Estás todo mojado!",
  ui_story_5008_50082101_4_dialog_content = "¡Toma mis pequeños duantes!",
  ui_story_5008_50082101_5_dialog_content = "No, no... Pescado, pescado, pescado...",
  ui_story_5008_50082101_6_dialog_content = "¡Espeda un segundo!",
  ui_story_5008_50082101_7_dialog_content = "Puse el pescado en el tanque... ¡y también dejé algunos bocadillos allí!",
  ui_story_5008_50082101_8_dialog_content = "Parece que les gusta estar aquí.",
  ui_story_5008_50082101_9_dialog_content = "¡Ciedto! ¡Ahoda los pequeños peces se ven tan felices!",
  ui_story_5008_50082101_10_dialog_content = "¿Te sientes mejod, Dove? ¿Aún con frío?",
  ui_story_5008_50082101_11_dialog_content = "<size=45>¡Coo—achoo!</size>",
  ui_story_5008_50082101_12_dialog_content = "Dove, es hora de que regreses e informes.",
  ui_story_5008_50082101_13_dialog_content = "Haré que el convoy te recoja en la oficina de correos más cercana.",
  ui_story_5008_50082101_14_dialog_content = "¿Hmm? ¿Se... acabó?",
  ui_story_5008_50082101_15_dialog_content = "Pero PlayerName aún no ha firmado, coo...",
  ui_story_5008_50082101_16_dialog_content = "¿Esto cuenta como terminar mi trabajo aquí?",
  ui_story_5008_50082101_17_dialog_content = "Quiero decir, la oficina de correos ni siquiera ha enviado una carta real todavía...",
  ui_story_5008_50082101_18_dialog_content = "Pero estás enfermo. Está bien, Dove.",
  ui_story_5008_50082101_19_dialog_content = "Vuelve y descansa. Le explicaré la situación a la jefa Vivian.",
  ui_story_5008_50082101_20_dialog_content = "¿Qué tal si te consigo otras dos semanas de licencia pagada?",
  ui_story_5008_50082101_21_dialog_content = "Sé lo difícil que ha sido este trabajo para ti.",
  ui_story_5008_50082101_22_dialog_content = "¿En serio? <size=45>¡Coo—achoo!</size>",
  ui_story_5008_50082101_23_dialog_content = "¿Puedo irme a casa y dormir ahora?",
  ui_story_5008_50082101_24_dialog_content = "Por supuesto.",
  ui_story_5008_50082101_25_dialog_content = "En nombre de Unión de Mensajería, te agradezco tus esfuerzos, Dove.",
  ui_story_5008_50082101_26_dialog_content = "Dove, ¿puedo ir a la sucursal de Illumina para jugar contigo alguna vez?",
  ui_story_5008_50082101_27_dialog_content = "Coo, seguro.",
  ui_story_5008_50082101_28_dialog_content = "Siempre que no esté ocupado con el trabajo y esté despierto.",
  ui_story_5008_50082101_29_dialog_content = "¿Ah? ¿Eso significa que nunca volveré a ver a Dove?",
  ui_story_5008_50082101_30_dialog_content = "¡Coo, también puedes ayudarme a entregar mis cartas!",
  ui_story_5008_50082101_31_dialog_content = "Dove, ¡parece que estás mejor ahora! ¡No estás estornudando en absoluto!",
  ui_story_5008_50082101_32_dialog_content = "¿¡Coo!? ¡Coo—achoo! ¡Coo—achoo! ¡Coo—achoo! ¡Coo—achoo!",
  ui_story_5008_50082101_33_dialog_content = "¡Entonces me iré! Todos... Erm... ¡Hasta la próxima!",
  ui_story_5008_50082101_34_dialog_content = "¡Vendré a jugad contigo pronto, Dove!",
  ui_story_5008_50082101_35_dialog_content = "Buena suerte a todo, Dove. La naturaleza velará por ti.",
  ui_story_5008_50082201_1_dialog_content = "¡Oh! ¡Naroxel, el gatito encontró un juguete nuevo!",
  ui_story_5008_50082201_2_dialog_content = "Este es un sombrero de Portador de correo",
  ui_story_5008_50082201_3_dialog_content = "¡Realmente ama este sombredo!",
  ui_story_5008_50082201_4_dialog_content = "Alguien del convoy debe haberlo dejado aquí.",
  ui_story_5008_50082201_5_dialog_content = "Verás, todavía hay un logotipo de Illumina tenue en él.",
  ui_story_5008_50082201_6_dialog_content = "Oh sí... ¡Tienes razón!",
  ui_story_5008_50082201_7_dialog_content = "¡Se frota la cabeza contra el sombrero! ¡Qué lindo gatito!",
  ui_story_5008_50082201_8_dialog_content = "Maulló de repente...",
  ui_story_5008_50082201_9_dialog_content = "¿Me pregunto qué quiere...?",
  ui_story_5008_50082201_10_dialog_content = "¿Ah? ¿Los gatitos no solo maúllan porque les apetece?",
  ui_story_5008_50082201_11_dialog_content = "No, Tweety.",
  ui_story_5008_50082201_12_dialog_content = "Cuando un gato maúlla, en realidad está tratando de decirte que quiere algo.",
  ui_story_5008_50082201_13_dialog_content = "Ahora...",
  ui_story_5008_50082201_14_dialog_content = "¡Lo se! El gatito ha estado mirando la pecera... ¡Debe querer comer pescado!",
  ui_story_5008_50082201_15_dialog_content = "Gatito, ¿no quieres comer pescado?",
  ui_story_5008_50082201_16_dialog_content = "¡Dove intentó con todas sus fuerzas atraparlo!",
  ui_story_5008_50082201_17_dialog_content = "No te preocupes por eso, Tweety.",
  ui_story_5008_50082201_18_dialog_content = "No es ese tipo de gato. Puedo sentirlo.",
  ui_story_5008_50082201_19_dialog_content = "Solo quiere jugar con estos pececillos un rato...",
  ui_story_5008_50082201_20_dialog_content = "No entiende por qué está tan cerca, pero todavía no puede tocar el pez.",
  ui_story_5008_50082201_21_dialog_content = "¿Oh? ¡Yo entiendo ahora!",
  ui_story_5008_50082201_22_dialog_content = "¡Oh sí! Naroxel, ¿no tenemos bocadillos de la unión que huelen a pescado de alcantarilla salado?",
  ui_story_5008_50082201_23_dialog_content = "¿Por qué no le damos un poco al gatito?",
  ui_story_5008_50082201_24_dialog_content = "Bien... Podemos intentarlo y ver si le gusta.",
  ui_story_5008_50082201_25_dialog_content = "No se lo des directamente. Simplemente déjelo en el suelo y, si está interesado, vendrá a buscarlo él mismo.",
  ui_story_5008_50082201_26_dialog_content = "¡El gatito saltó de su pequeña cama!",
  ui_story_5008_50082201_27_dialog_content = "¡El gatito se abalanzó sobre los bocadillos!",
  ui_story_5008_50082201_28_dialog_content = "¡El gatito está oliendo la herida!",
  ui_story_5008_50082201_29_dialog_content = "¡Uh-oh! ¡¡El gatito saltó!!",
  ui_story_5008_50082201_30_dialog_content = "Hmm... Él está bien. El olor era demasiado estimulante para él.",
  ui_story_5008_50082201_31_dialog_content = "¿Demasiado estimudante? No he probado este sabod antes... Déjame probadlo-",
  ui_story_5008_50082201_32_dialog_content = "Tweety, el gato acaba de saltar. No creo que debas-",
  ui_story_5008_50082201_33_dialog_content = "Sip. Está emocionado, está bien...",
  ui_story_5008_50082301_1_dialog_content = "¡Somos los mejores!",
  ui_story_5008_50082301_2_dialog_content = "Uf... ¡Este lugad ha sido decodado con un aspecto completamente nuevo!",
  ui_story_5008_50082301_3_dialog_content = "Solo queda una cosa...",
  ui_story_5008_50082301_4_dialog_content = "Esto. Colguemos esta lámpara de techo.",
  ui_story_5008_50082301_5_dialog_content = "¡Bien!",
  ui_story_5008_50082301_6_dialog_content = "Esto es... ¿una pequeño pollito godito?",
  ui_story_5008_50082301_7_dialog_content = "No, tal vez no. Su cola parece demasiado ladga...",
  ui_story_5008_50082301_8_dialog_content = "No es un pájaro. Esta es una representación del Coloso de PlayerName.",
  ui_story_5008_50082301_9_dialog_content = "Pero... ¡se ve mucho más brillante que su Colossus!",
  ui_story_5008_50082301_10_dialog_content = "Bueno, el gato me acaba de informar que este es en realidad el estilo en el que se celebra a Windelion.",
  ui_story_5008_50082301_11_dialog_content = "¡Wow! ¿Esta decoración forma parte de las costumbres festivas de los cedestitas?",
  ui_story_5008_50082301_12_dialog_content = "Sí, este tipo de decoración se llama efigie de viento.",
  ui_story_5008_50082301_13_dialog_content = "Vi la estructura general de esta efigie de viento en la parte posterior de sus planos de diseño.",
  ui_story_5008_50082301_14_dialog_content = "Pero cuando lo vi por primera vez, no tenía idea de que era una decoración de Windelion... Pensé que era algún tipo de dispositivo.",
  ui_story_5008_50082301_15_dialog_content = "Afortunadamente, el gato me lo dijo.",
  ui_story_5008_50082301_16_dialog_content = "Sin embargo, el proceso de producción para hacer esta efigie eólica no está escrito en los planos.",
  ui_story_5008_50082301_17_dialog_content = "Entonces, el que colgamos... De hecho, solo adiviné cómo se suponía que debía ensamblarse.",
  ui_story_5008_50082301_18_dialog_content = "Puede que no sea perfecto... pero fue lo mejor que pude manejar, así que PlayerName solo tendrá que conformarse con eso.",
  ui_story_5008_50082301_19_dialog_content = "¡Yo creo que es gedial!",
  ui_story_5008_50082301_20_dialog_content = "Déjame mostrarte lo que pienso PlayerName lo haré cuando entre!",
  ui_story_5008_50082301_21_dialog_content = "Voy a abrir la puerta, entonces PlayerName entra, se despierta, ve la muñeca windewion...",
  ui_story_5008_50082301_22_dialog_content = "Mmm...",
  ui_story_5008_50082301_23_dialog_content = "¿Qué te pasa, Tweety? ¿No lo colgamos correctamente?",
  ui_story_5008_50082301_24_dialog_content = "Bien... La ubicación parece buena, pero creo que esta efigie de viento es un poco pequeña.",
  ui_story_5008_50082301_25_dialog_content = "Es tan pequeño... ni siquiera es tan impresionante.",
  ui_story_5008_50082301_26_dialog_content = "Ya veo... Realmente no es una gran sorpresa.",
  ui_story_5008_50082301_27_dialog_content = "Naroxel, ¿hacemos una efigie de viento más grande?",
  ui_story_5008_50082301_28_dialog_content = "Hmm... ¡Podemos poner un montón de bocadillos de la unión en esta efigie de viento!",
  ui_story_5008_50082301_29_dialog_content = "¡Oh! ¡También podemos escribirle un pequeño mensaje!",
  ui_story_5008_50082301_30_dialog_content = "Entonces me esconderé en esa viga...",
  ui_story_5008_50082301_31_dialog_content = "Tan pronto como PlayerName entra, tiraré nuestra gran muñeca windewion!",
  ui_story_5008_50082301_32_dialog_content = "De esa manera, PlayerName ¡Puede ver la pequeña muñeca en el techo y comer los bocadillos en la grande!",
  ui_story_5008_50082301_33_dialog_content = "Sí, y nuestros mensajes.",
  ui_story_5008_50082301_34_dialog_content = "Gracias, Tweety. Creo que es una muy buena idea.",
  ui_story_5008_50082301_35_dialog_content = "¡Empecemos ahora!",
  ui_story_5008_50082301_36_dialog_content = "¡Yippee!",
  ui_story_5008_50082301_37_dialog_content = "Uf... ¡Finalmente terminamos la efigie del gran viento!",
  ui_story_5008_50082301_38_dialog_content = "Sí. Ciertamente no fue fácil...",
  ui_story_5008_50082301_39_dialog_content = "Podemos agregar los bocadillos y los mensajes ahora.",
  ui_story_5008_50082301_40_dialog_content = "Piolín, ¿qué sabor crees que PlayerName ¿podría gustar?",
  ui_story_5008_50082301_41_dialog_content = "Eché un vistazo, y parece que solo nos quedan los sabores \"Skunk Butt\", \"Stinky Sulfur\" y \"Rusty Iron Blade\".",
  ui_story_5008_50082301_42_dialog_content = "Y también está el sabor \"Teppanyaki Strawberry\" y \"Absolutely Fabulous\".",
  ui_story_5008_50082301_43_dialog_content = "no creo PlayerName elegiría Teppanyaki Stwawbewwies!",
  ui_story_5008_50082301_44_dialog_content = "¿Porqué crees?",
  ui_story_5008_50082301_45_dialog_content = "Porque cuando estaba trabajando en la recepción en Cwoud Mountain, escuché a alguien de la misma edad que PlayerName decir...",
  ui_story_5008_50082301_46_dialog_content = "\"¡Los hombres de vedad no comen fesas!\"",
  ui_story_5008_50082301_47_dialog_content = "Por eso pienso PlayerName probablemente también lo pensará...",
  ui_story_5008_50082301_48_dialog_content = "Supongo que tiene algún sentido...",
  ui_story_5008_50082301_49_dialog_content = "Entonces comamos el de fresa y pongamos los otros cuatro sabores.",
  ui_story_5008_50082301_50_dialog_content = "¡Oh sí! ¿Y qué vamos a escribir en el pequeño mensaje?",
  ui_story_5008_50082301_51_dialog_content = "Cualquier cosa alentadora debería estar bien.",
  ui_story_5008_50082301_52_dialog_content = "Muy bien, ¡lo tengo!",
  ui_story_5008_50082301_53_dialog_content = "\"Espero PlayerName siempre tiene mucho trabajo que hacer, ¡porque el trabajo es la cosa más maravillosa del mundo!",
  ui_story_5008_50082301_54_dialog_content = "\"¡Espero que seas cada vez más redondo, con manos grandes y redondas y una cabeza grande y redonda!\"",
  ui_story_5008_50082301_55_dialog_content = "\"Espero PlayerName es feliz, ¡todos los días!\"",
  ui_story_5008_50082301_56_dialog_content = "¡Finalizado!",
  ui_story_5008_50082301_57_dialog_content = "\"Que la naturaleza te bendiga, ahora y siempre\".",
  ui_story_5008_50082301_58_dialog_content = "\"Cada segundo que ha pasado se pierde para siempre en el río del tiempo. El momento más preciado siempre será el presente\".",
  ui_story_5008_50082301_59_dialog_content = "\"Por favor, abstente de dedicarte a la búsqueda de la eternidad... El ciclo infinito de la naturaleza ya ha elegido un camino para ti\".",
  ui_story_5008_50082301_60_dialog_content = "Pongamos los mensajes.",
  ui_story_5008_50082301_61_dialog_content = "¡Los até en la cola de este grandullón!",
  ui_story_5008_50082301_62_dialog_content = "¡Sacude, sacude! ¡Sacude, sacude, sacude!",
  ui_story_5008_50082301_63_dialog_content = "¡Oh, listo!",
  ui_story_5008_50082301_64_dialog_content = "Excelente. Bien hecho, Tweety.",
  ui_story_5008_50082301_65_dialog_content = "Ahora... Esperemos PlayerName regresar.",
  ui_story_5008_50082301_66_dialog_content = "Estoy deseando ver su rostro cuando abra esa puerta."
